  "composition--paragraph-fundamentals": {
   "title": "Unit 1: Fundamentals of Paragraph Writing",
   "courseId": "composition",
   "courseTitle": "Composition",
   "unitId": "paragraph-fundamentals",
   "description": "Master paragraph architecture: topic sentences, controlling ideas, and concluding statements.",
   "questions": [
    {
     "id": "co-pf-1",
     "q": "What are the two indispensable components of a strong academic 'Topic Sentence'?",
     "options": [
      "A famous quotation and a page citation.",
      "A specific topic and a controlling idea that states the writer's angle or argument.",
      "A rhetorical question and a dictionary definition.",
      "A transitional phrase and three statistical figures."
     ],
     "answer": 1,
     "explain": "An effective topic sentence pairs the topic with a controlling idea, limiting the scope and establishing the main argument of the paragraph."
    },
    {
     "id": "co-pf-2",
     "q": "Why is the statement 'Moulay Ismail University is located in Meknes, Morocco' weak as a topic sentence?",
     "options": [
      "It is grammatically incorrect.",
      "It is a simple statement of fact with no controlling idea or arguable point to develop.",
      "It is too complex for a standard paragraph.",
      "It does not contain an academic citation."
     ],
     "answer": 1,
     "explain": "A pure factual statement cannot serve as a topic sentence because it leaves nothing to explain, analyze, or prove in the supporting sentences."
    },
    {
     "id": "co-pf-3",
     "q": "What is the primary function of a paragraph's 'Concluding Sentence'?",
     "options": [
      "To introduce an entirely new argument not mentioned in the body.",
      "To reinforce the controlling idea by summarizing key points or offering a final insight, without introducing unrelated topics.",
      "To apologize for any points omitted from the paragraph.",
      "To repeat the topic sentence word-for-word."
     ],
     "answer": 1,
     "explain": "A concluding sentence synthesizes the paragraph's evidence, restates the controlling idea in fresh words, and provides closure."
    }
   ]
  },
