  "composition--revising-and-proofreading": {
   "title": "Unit 4: Revising & Proofreading",
   "courseId": "composition",
   "courseTitle": "Composition",
   "unitId": "revising-and-proofreading",
   "description": "Test understanding of macro revision vs micro proofreading, eliminating wordiness, and comma splices.",
   "questions": [
    {
     "id": "co-rp-1",
     "q": "What is the critical distinction between 'Revising' and 'Proofreading' in the writing process?",
     "options": [
      "Revising focuses on global elements (ideas, organization, audience, thesis, paragraph order); proofreading focuses on surface mechanics (spelling, typos, punctuation).",
      "Proofreading is done before drafting; revising is done after printing.",
      "Revising is done only by the instructor; proofreading is done by software.",
      "There is no difference; both mean checking comma placement."
     ],
     "answer": 0,
     "explain": "Revision ('re-visioning') tackles high-level structure, logic, and arguments; proofreading is the final polish catching mechanical errors and typos."
    },
    {
     "id": "co-rp-2",
     "q": "How can a writer correct a 'comma splice' error (e.g., 'The thesis was accepted, the defense was scheduled for June')?",
     "options": [
      "Delete the comma without adding any punctuation.",
      "Separate into two complete sentences with a period, use a semicolon, or add a coordinating conjunction (e.g., ', and').",
      "Replace the comma with a hyphen.",
      "Convert the entire sentence to passive voice."
     ],
     "answer": 1,
     "explain": "A comma splice joins two independent clauses with only a comma. It is repaired with a period, a semicolon, or a comma + coordinating conjunction."
    },
    {
     "id": "co-rp-3",
     "q": "Which revised sentence best eliminates bureaucratic wordiness without losing meaning?",
     "options": [
      "Original: 'Due to the fact that the students were exhausted, they ceased working.' -> Revision: 'Because the students were exhausted, they stopped working.'",
      "Original: 'At this point in time...' -> Revision: 'In terms of the current temporal status...'",
      "Original: 'In my personal opinion, I think that...' -> Revision: 'From my own personal viewpoint, I believe that...'",
      "Original: 'The reason why is because...' -> Revision: 'The causative underlying rationale is that...'"
     ],
     "answer": 0,
     "explain": "Pruning deadwood phrases ('Due to the fact that' -> 'Because', 'ceased working' -> 'stopped working') makes academic prose direct, crisp, and readable."
    }
   ]
  },
